// src/db/sql.ts
function splitStatements(sql) {
  return sql.split("\n").filter((line) => !line.trim().startsWith("--")).join("\n").split(";").map((statement) => statement.trim()).filter((statement) => statement.length > 0);
}

// src/db/apply.ts
var MIGRATIONS_TABLE_DDL = `CREATE TABLE IF NOT EXISTS d1_migrations (
	id INTEGER PRIMARY KEY AUTOINCREMENT,
	name TEXT UNIQUE,
	applied_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP
)`;
async function applyMigrations(driver) {
  await driver.exec(MIGRATIONS_TABLE_DDL);
  const rows = await driver.all("SELECT name FROM d1_migrations");
  const recorded = new Set(rows.map((row) => row.name));
  const applied = [];
  for (const file of MIGRATION_FILES) {
    if (recorded.has(file.name)) continue;
    for (const statement of splitStatements(file.sql)) {
      await driver.exec(statement);
    }
    await driver.run("INSERT INTO d1_migrations (name) VALUES (?)", [file.name]);
    applied.push(file.name);
  }
  return {
    applied,
    alreadyApplied: MIGRATION_FILES.map((file) => file.name).filter((name) => recorded.has(name))
  };
}

// src/db/d1.ts
function createD1Driver(binding) {
  return {
    kind: "d1",
    async exec(sql) {
      await binding.prepare(sql).run();
    },
    async all(sql, params = []) {
      const result = await binding.prepare(sql).bind(...params).all();
      return result.results ?? [];
    },
    async first(sql, params = []) {
      return await binding.prepare(sql).bind(...params).first();
    },
    async run(sql, params = []) {
      const result = await binding.prepare(sql).bind(...params).run();
      return { changes: result.meta?.changes ?? 0 };
    },
    async batch(statements) {
      await binding.batch(
        statements.map((statement) => binding.prepare(statement.sql).bind(...statement.params ?? []))
      );
    },
    close() {
    }
  };
}

// src/db/node-sqlite.ts
var SQLITE_MODULE = "node:sqlite";
var FS_MODULE = "node:fs";
var PATH_MODULE = "node:path";
async function createNodeSqliteDriver(file) {
  const { mkdirSync } = await import(FS_MODULE);
  const { dirname } = await import(PATH_MODULE);
  const { DatabaseSync: SqliteDatabase } = await import(SQLITE_MODULE);
  if (file !== ":memory:") {
    mkdirSync(dirname(file), { recursive: true });
  }
  const db = new SqliteDatabase(file);
  db.exec("PRAGMA foreign_keys = ON");
  return {
    kind: "node-sqlite",
    async exec(sql) {
      db.prepare(sql).run();
    },
    async all(sql, params = []) {
      return db.prepare(sql).all(...params);
    },
    async first(sql, params = []) {
      return db.prepare(sql).get(...params) ?? null;
    },
    async run(sql, params = []) {
      const result = db.prepare(sql).run(...params);
      return { changes: Number(result.changes) };
    },
    async batch(statements) {
      db.exec("BEGIN");
      try {
        for (const statement of statements) {
          db.prepare(statement.sql).run(...statement.params ?? []);
        }
        db.exec("COMMIT");
      } catch (error) {
        try {
          db.exec("ROLLBACK");
        } catch {
        }
        throw error;
      }
    },
    close() {
      db.close();
    }
  };
}

// src/db/types.ts
function isD1Database(value) {
  if (typeof value !== "object" || value === null) return false;
  const candidate = value;
  return typeof candidate.prepare === "function" && typeof candidate.exec === "function";
}

// src/db/index.ts
var DEFAULT_DB_FILE = ".data/excited-live.sqlite";
var DB_FILE_ENV = "EXCITED_API_DB_PATH";
var AUTO_MIGRATE_ENV = "EXCITED_API_AUTO_MIGRATE";
function resolveDbFile(env = process.env) {
  return env[DB_FILE_ENV] || DEFAULT_DB_FILE;
}
function autoMigrateEnabled(env = process.env) {
  return env[AUTO_MIGRATE_ENV] !== "0";
}
async function resolveDb(env, processEnv = process.env) {
  const binding = typeof env === "object" && env !== null ? env.DB : void 0;
  const driver = isD1Database(binding) ? createD1Driver(binding) : await createNodeSqliteDriver(resolveDbFile(processEnv));
  const location = driver.kind === "d1" ? "DB (D1 binding)" : resolveDbFile(processEnv);
  const report = autoMigrateEnabled(processEnv) ? await applyMigrations(driver) : { applied: [], alreadyApplied: [] };
  return { driver, mode: driver.kind, location, migrations: report.applied };
}
var cached = null;
function getDb(env) {
  cached ??= resolveDb(env);
  return cached;
}

